"use client"

import { useEffect, useState } from "react"
import { cn } from "@/lib/utils"

interface HeroOverlayProps {
  /** Milliseconds after mount before the overlay slides up. Default: 7000 */
  delay?: number
}

export function HeroOverlay({ delay = 7000 }: HeroOverlayProps) {
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const timer = setTimeout(() => setVisible(true), delay)
    return () => clearTimeout(timer)
  }, [delay])

  return (
    <div
      className={cn(
        // Covers the full hero, sits above video (z-20) but below foreground content (z-10 is fg)
        "absolute inset-0 z-20",
        // Black at 80% opacity + background blur applied to the overlay itself
        "bg-black/40 backdrop-blur-lg",
        // Fade in from 0 to full opacity
        "transition-opacity duration-1200 ease-in-out",
        visible ? "opacity-100" : "opacity-0"
      )}
      aria-hidden="true"
    />
  )
}
